-- Source data: data/town-center-stock.csv, data/town-center-items.csv,
--              data/vendor_npc_ids.csv, generated/source-asset-index.csv

DELETE FROM `housing_decor` WHERE `id` BETWEEN 2000 AND 2899;

-- The four pet beds, sold by the Pet Handler. Entries are cages this tree
-- declares; the display name is filled from gameobject_template at install like
-- every other native piece.
DELETE FROM `housing_decor` WHERE `id` BETWEEN 2950 AND 2959;

-- Every row above must resolve to a template that has a model. This report is
-- expected to return nothing; a row here is a piece that would stand in a yard
-- invisible, which is worse than a piece that is missing from the catalogue.

SELECT hd.`id`, hd.`gameobject_entry`, hd.`name` AS `catalogue_name`, gt.`name`
FROM `housing_decor` hd
LEFT JOIN `gameobject_template` gt ON gt.`entry` = hd.`gameobject_entry`
WHERE hd.`id` BETWEEN 2000 AND 2959 AND (gt.`entry` IS NULL OR gt.`displayId` = 0);


-- Display names come from the world DB, not from the constant name:
UPDATE `housing_decor` hd JOIN `gameobject_template` gt
  ON gt.`entry` = hd.`gameobject_entry`
SET hd.`name` = gt.`name`
WHERE hd.`id` BETWEEN 2000 AND 2959 AND gt.`name` <> '';
